(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-582":{scenario:{company:"Kim Long Precision Molds",supervisor:{name:"Đặng Minh Quân",role:{vi:"Trưởng nhóm Thiết kế Khuôn",en:"Mold Design Lead"}},ref_code:"MD-4471",title:{vi:"Đủ lực kẹp. Đúng máy ép. Tôn trọng bản quyền thiết kế.",en:"Enough clamp force. Right press. Respect design rights."},brief:{vi:"Khuôn MD-4471 ép nắp hộp nhựa PP, 4 lòng khuôn, diện tích chiếu mỗi lòng 80 cm2, kênh dẫn và cổng phun 30 cm2. Phân tích điền đầy cho áp suất lòng khuôn 400 kgf/cm2 (mô phỏng), hệ số an toàn 1.15. Bảng đề xuất nháp chọn máy ép chưa đúng. Đối chiếu với tiêu chuẩn thiết kế khuôn đã duyệt, sửa lực kẹp yêu cầu (tấn lực) và máy ép, rồi lập báo cáo có căn cứ.",en:"Mold MD-4471 produces PP box lids with 4 cavities, 80 cm2 projected area per cavity and 30 cm2 for runners and gates. Fill analysis gives a cavity pressure of 400 kgf/cm2 (training value) and the safety factor is 1.15. The draft proposal picks the wrong press. Check it against the approved mold design standard, correct the required clamp force (tonnes-force) and the press, then write an evidence-based report."},reference_title:{vi:"Tiêu chuẩn thiết kế khuôn và danh sách máy ép đã duyệt · MD-4471",en:"Approved mold design standard and press list · MD-4471"},fields:[{id:"PRESS",label:{vi:"Máy ép được chọn",en:"Selected injection press"},initial:"150T",expected:"180T",choices:["150T","180T","250T"],reference:"Danh sách máy ép xưởng",hint:{vi:"Chọn máy nhỏ nhất có lực kẹp định mức không thấp hơn lực kẹp yêu cầu đã nhân hệ số an toàn.",en:"Choose the smallest press whose rated clamp force is not below the required force including the safety factor."}},{id:"CLAMP_TF",label:{vi:"Lực kẹp yêu cầu (tấn lực)",en:"Required clamp force (tf)"},initial:"128",expected:"161",reference:"Bảng tính lực kẹp khuôn",ref_value:{vi:"4 lòng x 80 cm2; kênh dẫn 30 cm2; áp suất 400 kgf/cm2; hệ số an toàn 1.15",en:"4 cavities x 80 cm2; runners 30 cm2; pressure 400 kgf/cm2; safety factor 1.15"},hint:{vi:"Diện tích chiếu phải gồm cả kênh dẫn, cổng phun; đừng quên hệ số an toàn.",en:"Projected area must include runners and gates; do not forget the safety factor."}}],sop32:{vi:"Lực kẹp (tf) = (số lòng x diện tích chiếu mỗi lòng + diện tích kênh dẫn) x áp suất lòng khuôn x hệ số an toàn / 1000; chọn máy nhỏ nhất có lực kẹp định mức ≥ lực yêu cầu.",en:"Clamp force (tf) = (cavities x projected area per cavity + runner area) x cavity pressure x safety factor / 1000; choose the smallest press rated ≥ the required force."},context:{label:"MOLD DESIGN / MD-4471",metrics:[{label:{vi:"Số lòng khuôn",en:"Cavities"},value:"4"},{label:{vi:"Diện tích chiếu mỗi lòng",en:"Projected area per cavity"},value:"80 cm2"},{label:{vi:"Áp suất lòng khuôn mô phỏng",en:"Training cavity pressure"},value:"400 kgf/cm2"}]},terminal:{system:"mold-sim",settable:["PRESS","CLAMP_TF"],commands:[{cmd:"status",out:{vi:"Dự án MD-4471: khuôn 2 tấm, 4 lòng, nhựa PP; đề xuất nháp CLAMP_TF=128, PRESS=150T",en:"Project MD-4471: 2-plate mold, 4 cavities, PP resin; draft proposal CLAMP_TF=128, PRESS=150T"}},{cmd:"cat part_spec.txt",out:{vi:"Nắp hộp 120 x 66.7 mm, diện tích chiếu mỗi sản phẩm 80 cm2, chiều dày thành 1.6 mm",en:"Lid 120 x 66.7 mm, projected area per part 80 cm2, wall thickness 1.6 mm"}},{cmd:"cat runner.txt",out:{vi:"Hệ kênh dẫn nguội hình chữ H và 4 cổng phun cạnh: diện tích chiếu 30 cm2",en:"H-shaped cold runner and 4 edge gates: projected area 30 cm2"}},{cmd:"fill-analysis",out:{vi:"Áp suất lòng khuôn lớn nhất tại điểm chuyển V/P: 400 kgf/cm2 (mô phỏng); cảnh báo nguy cơ bavia nếu lực kẹp thiếu",en:"Peak cavity pressure at V/P switchover: 400 kgf/cm2 (training value); flash risk warning if clamp force is short"}},{cmd:"cat press_list.txt",out:{vi:"Máy sẵn có: 150T, 180T, 250T; khoảng cách giữa các trụ đều đủ cho kích thước khuôn",en:"Available presses: 150T, 180T, 250T; tie-bar spacing fits the mold on all of them"}}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn: “Khách mới muốn nắp hộp giống hệt của khách cũ. Lấy file CAD khuôn của khách cũ sửa logo là xong, khỏi thiết kế lại, họ không biết đâu.”",en:"The sales manager messages: “The new client wants a lid identical to our old client's. Take the old client's mold CAD file, change the logo and we are done, they will never know.”"},options:{safe:{vi:"Từ chối dùng file CAD của khách cũ vì thuộc bảo mật và quyền sở hữu của họ; báo trưởng nhóm, đề nghị thiết kế độc lập từ yêu cầu và bản vẽ của khách mới.",en:"Refuse to reuse the old client's CAD file since it is confidential and their property; inform the lead and propose an independent design from the new client's own requirements and drawings."},shortcut:{vi:"Sao chép file CAD cũ, đổi logo và kích thước nhỏ để kịp báo giá.",en:"Copy the old CAD file, change the logo and a few dimensions to make the quote."},wait:{vi:"Không trả lời và để kinh doanh tự tìm người làm.",en:"Do not reply and let sales find someone else to do it."}},questions:{vi:["Vì sao lực kẹp đúng là 161 tấn lực và máy 180T phù hợp hơn 150T? Nếu ép trên máy 150T, sản phẩm sẽ gặp lỗi gì?","Dữ liệu CAD của khách hàng được bảo vệ thế nào, và bạn đề xuất cách đáp ứng khách mới hợp pháp ra sao?"],en:["Why is the correct clamp force 161 tf and why does the 180T press fit better than 150T? What defects appear if you mold on 150T?","How is customer CAD data protected, and how do you propose to serve the new client lawfully?"]},hints:{vi:["Đặt bảng đề xuất nháp cạnh danh sách máy ép và kiểm tra quy tắc chọn máy.","Áp dụng SOP mục 3.2: cộng diện tích kênh dẫn vào tổng diện tích chiếu rồi nhân áp suất và hệ số an toàn.","Đọc lại SOP mục 4.2: dữ liệu thiết kế của khách hàng chỉ dùng cho dự án của chính họ."],en:["Place the draft proposal next to the press list and check the selection rule.","Apply SOP 3.2: add the runner area to the total projected area, then apply pressure and safety factor.","Re-read SOP 4.2: customer design data may only be used for that customer's own project."]}},learning:{summary:{vi:"Kỹ sư Thiết kế Cơ khí và Khuôn mẫu dùng CAD, CAM, CAE để thiết kế sản phẩm, khuôn ép nhựa, khuôn dập và đồ gá, lập trình gia công CNC và mô phỏng kỹ thuật trước khi chế tạo. Giá trị tạo ra là khuôn chạy ổn định ngay từ lần thử đầu, sản phẩm đúng dung sai, chi phí và thời gian phát triển thấp. Công việc đòi hỏi vững vật liệu, gia công, dung sai và bảo mật dữ liệu khách hàng.",en:"A Mechanical CAD/CAM/CAE Engineer uses CAD, CAM and CAE to design products, injection molds, stamping dies and fixtures, program CNC machining and simulate before manufacture. The value is a mold that runs stably from the first trial, parts within tolerance and low development cost and time. The role requires solid knowledge of materials, machining, tolerances and customer data confidentiality."},responsibilities:{vi:["Phân tích bản vẽ sản phẩm, đánh giá khả năng chế tạo (DFM) và đề xuất sửa thiết kế.","Thiết kế khuôn 3D: mặt phân khuôn, hệ kênh dẫn, làm nguội, đẩy sản phẩm, thoát khí.","Mô phỏng điền đầy, cong vênh, phân tích bền và chọn máy ép phù hợp.","Lập trình CAM, chọn dao, chế độ cắt và kiểm tra va chạm trước khi gia công.","Lập bản vẽ 2D có GD&T, quản lý phiên bản và lưu trữ dữ liệu theo dự án."],en:["Analyse part drawings, assess manufacturability (DFM) and propose design changes.","Design 3D molds: parting surface, runners, cooling, ejection and venting.","Simulate filling, warpage and strength and select the right press.","Program CAM, choose tools and cutting data and check collisions before machining.","Produce 2D drawings with GD&T, control revisions and archive data by project."]},competencies:[{name:{vi:"Mô hình hóa CAD",en:"CAD modelling"},desc:{vi:"Dựng mô hình tham số, bề mặt phức tạp và lắp ráp khuôn đầy đủ chi tiết tiêu chuẩn.",en:"Build parametric models, complex surfaces and full mold assemblies with standard parts."}},{name:{vi:"Mô phỏng CAE",en:"CAE simulation"},desc:{vi:"Thiết lập lưới, điều kiện biên, đọc kết quả điền đầy, cong vênh, ứng suất và đánh giá độ tin cậy.",en:"Set up meshes and boundary conditions, read fill, warpage and stress results and judge their reliability."}},{name:{vi:"Lập trình CAM",en:"CAM programming"},desc:{vi:"Tạo đường chạy dao tối ưu, kiểm soát dư lượng và độ nhám bề mặt.",en:"Create efficient toolpaths and control stock allowance and surface finish."}},{name:{vi:"Dung sai và GD&T",en:"Tolerancing and GD&T"},desc:{vi:"Đặt dung sai hình học, chuỗi kích thước và lắp ghép phù hợp chức năng.",en:"Apply geometric tolerances, tolerance stacks and functional fits."}},{name:{vi:"Bảo mật dữ liệu thiết kế",en:"Design data confidentiality"},desc:{vi:"Tuân thủ thỏa thuận bảo mật, phân quyền truy cập và không tái sử dụng dữ liệu của khách khác.",en:"Honour NDAs, control access and never reuse another customer's data."}}],knowledge:{vi:["ISO 1101 và ASME Y14.5 về dung sai hình học và vị trí (GD&T).","ISO 286 về hệ thống dung sai và lắp ghép kích thước.","Đặc tính nhựa nhiệt dẻo: độ co ngót, nhiệt độ gia công, góc thoát khuôn.","Nguyên lý tính lực kẹp, thiết kế hệ làm nguội và cân bằng dòng chảy nhiều lòng khuôn.","Luật Sở hữu trí tuệ và nghĩa vụ bảo mật theo hợp đồng đối với kiểu dáng, dữ liệu thiết kế."],en:["ISO 1101 and ASME Y14.5 on geometric dimensioning and tolerancing (GD&T).","ISO 286 on the system of limits and fits.","Thermoplastic properties: shrinkage, processing temperature and draft angles.","Clamp force calculation, cooling design and flow balancing for multi-cavity molds.","Intellectual property law and contractual confidentiality for designs and design data."]},tools:["Phần mềm CAD 3D tham số","Phần mềm CAM gia công CNC","Phần mềm mô phỏng ép phun","Phần mềm phân tích phần tử hữu hạn","Máy đo tọa độ CMM"],kpis:{vi:["Tỷ lệ khuôn đạt ngay ở lần thử T1.","Số lần sửa khuôn sau thử trên mỗi dự án.","Thời gian thiết kế so với kế hoạch.","Số sự cố rò rỉ dữ liệu thiết kế (mục tiêu bằng 0)."],en:["Share of molds passing at the first T1 trial.","Mold corrections after trials per project.","Design lead time versus plan.","Design data leakage incidents (target zero)."]},day:[{time:"08:00",vi:"Rà soát bản vẽ sản phẩm mới, ghi các điểm cần góc thoát và đổi chiều dày.",en:"Review a new part drawing and mark spots needing draft and thickness changes."},{time:"09:30",vi:"Chạy mô phỏng điền đầy, kiểm tra đường hàn, bọt khí và áp suất lòng khuôn.",en:"Run a fill simulation and check weld lines, air traps and cavity pressure."},{time:"11:00",vi:"Họp DFM với khách hàng, thống nhất vị trí cổng phun và mặt phân khuôn.",en:"Hold a DFM meeting with the client to agree gate location and parting line."},{time:"14:00",vi:"Lập trình CAM cho tấm lòng khuôn, kiểm tra va chạm dao và đồ gá.",en:"Program CAM for the cavity plate and check tool and fixture collisions."},{time:"16:30",vi:"Phát hành bản vẽ, cập nhật phiên bản và lưu dữ liệu vào thư mục dự án có phân quyền.",en:"Release drawings, update revisions and file data in the access-controlled project folder."}],mistakes:{vi:["Tính lực kẹp chỉ theo diện tích sản phẩm, bỏ qua kênh dẫn và hệ số an toàn.","Dùng hệ số co ngót của vật liệu khác khiến kích thước sản phẩm sai.","Tái sử dụng dữ liệu CAD của khách hàng khác, vi phạm bảo mật và quyền sở hữu."],en:["Computing clamp force from part area only, ignoring runners and safety factor.","Using another material's shrinkage factor, leading to wrong part dimensions.","Reusing another customer's CAD data, breaching confidentiality and ownership."]},career:[{vi:"Kỹ thuật viên thiết kế CAD",en:"CAD design technician"},{vi:"Kỹ sư thiết kế khuôn",en:"Mold design engineer"},{vi:"Kỹ sư trưởng CAE và khuôn mẫu",en:"Lead CAE and tooling engineer"},{vi:"Trưởng phòng kỹ thuật khuôn mẫu",en:"Head of tooling engineering"}],glossary:[{term:"Projected area",vi:"Diện tích hình chiếu của sản phẩm và kênh dẫn lên mặt phân khuôn, dùng để tính lực kẹp.",en:"Area of the part and runners projected onto the parting plane, used to compute clamp force."},{term:"Flash",vi:"Bavia, nhựa tràn qua mặt phân khuôn do lực kẹp thiếu hoặc khuôn mòn.",en:"Plastic leaking through the parting line due to low clamp force or mold wear."},{term:"V/P switchover",vi:"Điểm chuyển từ điều khiển tốc độ phun sang điều khiển áp suất giữ.",en:"The point where injection switches from velocity control to pressure holding."},{term:"DFM",vi:"Thiết kế cho sản xuất, điều chỉnh sản phẩm để dễ chế tạo, ít lỗi và rẻ hơn.",en:"Design for manufacturing, adapting a part so it is easier and cheaper to make."},{term:"GD&T",vi:"Hệ thống ký hiệu dung sai hình học và vị trí mô tả yêu cầu chức năng của chi tiết.",en:"Geometric dimensioning and tolerancing describing a part's functional requirements."}],quiz:[{q:{vi:"Khuôn 2 lòng, mỗi lòng 50 cm2, kênh dẫn 20 cm2, áp suất 500 kgf/cm2, hệ số an toàn 1.2. Lực kẹp yêu cầu là bao nhiêu?",en:"A 2-cavity mold, 50 cm2 per cavity, 20 cm2 runners, 500 kgf/cm2 pressure, safety factor 1.2. What clamp force is required?"},options:{vi:["60 tf","50 tf","72 tf","36 tf"],en:["60 tf","50 tf","72 tf","36 tf"]},answer:2,explain:{vi:"Lực kẹp = (2 x 50 + 20) x 500 x 1.2 / 1000 = 72 tấn lực.",en:"Clamp force = (2 x 50 + 20) x 500 x 1.2 / 1000 = 72 tf."}},{q:{vi:"Lực kẹp máy ép thấp hơn lực mở khuôn do áp suất phun gây ra sẽ dẫn tới lỗi gì?",en:"What defect results when press clamp force is below the mold-opening force from injection pressure?"},options:{vi:["Bavia ở mặt phân khuôn","Vết lõm do co ngót","Cháy khí đầu dòng","Sản phẩm thiếu nhựa do nguội sớm"],en:["Flash at the parting line","Sink marks from shrinkage","Burn marks at flow front","Short shot from early freezing"]},answer:0,explain:{vi:"Khuôn bị đẩy hé mở, nhựa tràn qua mặt phân khuôn tạo bavia.",en:"The mold is pushed slightly open and plastic escapes through the parting line as flash."}},{q:{vi:"Kinh doanh bảo dùng file CAD của khách cũ cho khách mới. Bạn làm gì?",en:"Sales asks you to reuse an old client's CAD file for a new client. What do you do?"},options:{vi:["Làm theo nhưng đổi logo","Gửi file cho khách mới tự sửa","Dùng một nửa dữ liệu cũ","Từ chối và đề xuất thiết kế độc lập từ yêu cầu của khách mới"],en:["Comply but change the logo","Send the file to the new client","Use half of the old data","Refuse and propose an independent design from the new client's needs"]},answer:3,explain:{vi:"Dữ liệu thiết kế thuộc khách hàng cũ theo hợp đồng bảo mật; dùng lại là vi phạm.",en:"The design data belongs to the old client under the NDA; reusing it is a breach."}},{q:{vi:"Kích thước lòng khuôn cần lớn hơn kích thước sản phẩm chủ yếu vì lý do nào?",en:"Why must cavity dimensions be larger than part dimensions?"},options:{vi:["Để dễ đánh bóng","Để bù co ngót của nhựa khi nguội","Để tăng lực kẹp","Để giảm thời gian chu kỳ"],en:["For easier polishing","To compensate for plastic shrinkage on cooling","To raise clamp force","To shorten cycle time"]},answer:1,explain:{vi:"Nhựa co khi nguội, nên lòng khuôn được phóng to theo hệ số co ngót của vật liệu.",en:"Plastic shrinks as it cools, so the cavity is scaled up by the material's shrinkage factor."}}],tools_en:["Parametric 3D CAD software","CNC machining CAM software","Injection molding simulation software","Finite element analysis (FEA) software","Coordinate measuring machine (CMM)"]}}})})(window.KKR);
